from taf.ul.ettf.ta_matchers.matchers import Any, Omit, Perm


csr_two_layers = 0x00000000ffffffff
csr_four_layers = 0xffffffffffffffff
csr_four_layers_tm9 = 0xf000ffffffffffff
csr_two_layers_2x2 = 0xfc
four_layers_setup = Any({'maxLayersMIMO-r10': 'fourLayers'})
two_layers_setup = Any({'maxLayersMIMO-r10': 'twoLayers'})
four_layers_release = Any({'maxLayersMIMO-r10': Omit()})
antennaInfoUL_r10_message = Any({'AntennaInfoUL-r10'})


def ul_configuration(ul_earfcn=Omit()):
    return \
        Any({'ul-Configuration-r10':
             Any({'ul-FreqInfo-r10':
                  Any({'ul-CarrierFreq-r10': ul_earfcn
                       })
                  })
             })


def template_antenna_info(csr=Any(), tm=Any()):
    return \
        Any({
            'codebookSubsetRestriction-r10': csr,
            'transmissionMode-r10': tm
        })


def cell_identification(cell_id=Any(), dl_carrier_freq=Any()):
    return \
        Any({
            'physCellId-r10': cell_id,
            'dl-CarrierFreq-r10': dl_carrier_freq
        })


def template_scell(antenna_info, antenna_info_v10i0=Omit(), cell_identification=None, cell_index=None):
    return \
        Any({
            'sCellIndex-r10': cell_index if cell_index is not None else Any(),
            'cellIdentification-r10': cell_identification if cell_identification is not None else Any(),
            'antennaInfoDedicatedSCell-v10i0': antenna_info_v10i0,
            'radioResourceConfigDedicatedSCell-r10':
                Any({'physicalConfigDedicatedSCell-r10':
                     Any({'nonUL-Configuration-r10':
                          Any({'antennaInfo-r10': antenna_info}) if antenna_info is not None else Omit()
                          })
                     })
        })


def template_scell_addition(scells, antenna_info_pcell=None, antenna_info_v10i0_pcell=None):
    return \
        Any({
            'radioResourceConfigDedicated':
                Any({'physicalConfigDedicated':
                     Any({'antennaInfo-r10':
                          Any({
                              'explicitValue-r10': antenna_info_pcell}) if antenna_info_pcell is not None else Omit()
                          })
                     }),
            'nonCriticalExtension':
                Any({
                    'nonCriticalExtension':
                        Any({'nonCriticalExtension':
                             Any({'sCellToAddModList-r10': Perm(*scells) if scells else Omit()})
                             }),
                    'lateNonCriticalExtension':
                    Any({'RRCConnectionReconfiguration-v8m0-IEs':
                         Any({'nonCriticalExtension':
                              Any({'antennaInfoDedicatedPCell-v10i0': antenna_info_v10i0_pcell})
                              })
                         }) if antenna_info_v10i0_pcell is not None else Omit()
                })
        })


def template_ics(antenna_info, is_v10i0_four_layers=False):
    return \
        Any({
            'radioResourceConfigDedicated':
                Any({'physicalConfigDedicated':
                     Any({'antennaInfo-r10':
                          Any({'explicitValue-r10': antenna_info})
                          })
                     }),
            'nonCriticalExtension':
                Any({'lateNonCriticalExtension':
                     Any({'RRCConnectionReconfiguration-v8m0-IEs':
                          Any({'nonCriticalExtension':
                               Any({'antennaInfoDedicatedPCell-v10i0': four_layers_setup})
                               })
                          })
                     }) if is_v10i0_four_layers else Omit()
        })


def template_scell_ul(antenna_info, antenna_info_v10i0=Omit(), ul_configuration=Any()):
    return \
        Any({
            'antennaInfoDedicatedSCell-v10i0': antenna_info_v10i0,
            'radioResourceConfigCommonSCell-r10': ul_configuration,
            'radioResourceConfigDedicatedSCell-r10':
                Any({'physicalConfigDedicatedSCell-r10':
                     Any({'nonUL-Configuration-r10':
                          Any({'antennaInfo-r10': antenna_info})
                          })
                     })
        })


def ics_two_layers():
    return template_ics(antenna_info=template_antenna_info(csr=csr_two_layers), is_v10i0_four_layers=False)


def ics_four_layers():
    return template_ics(antenna_info=template_antenna_info(csr=csr_four_layers), is_v10i0_four_layers=True)


def ics_four_layers_without_v10i0():
    return template_ics(antenna_info=template_antenna_info(csr=csr_four_layers), is_v10i0_four_layers=False)


def ics_four_layers_tm4():
    return template_ics(antenna_info=template_antenna_info(csr=csr_four_layers, tm='tm4'), is_v10i0_four_layers=True)


def ics_four_layers_tm9():
    return template_ics(antenna_info=template_antenna_info(csr=csr_four_layers_tm9, tm='tm9-v1020'),
                        is_v10i0_four_layers=False)
